let sceneStarted=false;const sceneTimers=[];
function startKrishnaOpening(){if(sceneStarted)return;sceneStarted=true;document.body.style.overflow='hidden';const scene=document.createElement('div');scene.className='krishna-opening';scene.setAttribute('role','dialog');scene.setAttribute('aria-modal','true');scene.setAttribute('aria-label','Light the diyas to celebrate Dhiraj and Neha');const positions=[[50,84,85],[12,88,68],[28,82,62],[72,82,62],[88,88,68],[18,73,53],[82,73,53],[26,65,44],[74,65,44],[32,58,35],[68,58,35],[36,52,28],[64,52,28]];scene.innerHTML='<div class="opening-garden"></div><div class="opening-sky"></div><div class="opening-caption">जय श्री कृष्णा<br><span style="font:11px DM Sans,sans-serif;letter-spacing:3px">A CELEBRATION OF LOVE</span></div><div class="diya-trail">'+positions.map(([x,y,s],i)=>`<div class="scene-diya ${i===0?'lit':''}" style="left:${x}%;top:${y}%;--lamp-size:${s}px"><img src="diya-lamp.svg" alt=""></div>`).join('')+'</div>'+[[25,20,240,0],[73,15,260,.6],[48,28,210,1.1],[15,35,180,1.7],[85,34,200,2.1]].map(([x,y,s,d])=>`<div class="opening-firework" style="left:${x}%;top:${y}%;--burst-size:${s}px;--burst-delay:${d}s"><img src="golden-firework.svg" alt=""></div>`).join('')+'<button class="light-diyas">Tap to light the diyas ✨</button><div class="opening-names"><p>WITH KRISHNA’S BLESSINGS</p><h2>Dhiraj & Neha</h2><button class="opening-continue">Read the invitation ↓</button></div><button class="opening-skip">Skip opening →</button><div class="scene-status" role="status" style="position:absolute;width:1px;height:1px;overflow:hidden"></div>';document.body.append(scene);let lighting=false;const finish=()=>{sceneTimers.forEach(clearTimeout);scene.classList.add('finished');document.body.style.overflow='';document.querySelector('.hero h1').focus({preventScroll:true});setTimeout(()=>scene.remove(),1200)};scene.querySelector('.opening-skip').onclick=finish;scene.querySelector('.opening-continue').onclick=finish;scene.addEventListener('keydown',e=>{if(e.key==='Escape')finish();if(e.key==='Tab'){const buttons=[...scene.querySelectorAll('button')].filter(b=>getComputedStyle(b).pointerEvents!=='none');const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});scene.querySelector('.light-diyas').onclick=()=>{if(lighting)return;lighting=true;scene.classList.add('illuminated');scene.querySelector('.scene-status').textContent='The diyas are lighting up.';scene.querySelectorAll('.scene-diya').forEach((lamp,i)=>sceneTimers.push(setTimeout(()=>lamp.classList.add('lit'),motion?0:i*140)));sceneTimers.push(setTimeout(()=>scene.classList.add('celebrating'),motion?100:2100));sceneTimers.push(setTimeout(()=>{scene.classList.add('revealing');scene.querySelector('.scene-status').textContent='Dhiraj and Neha. Your invitation is ready.';scene.querySelector('.opening-continue').focus()},motion?200:4800))};scene.querySelector('.light-diyas').focus()}
new MutationObserver(()=>{if(gate.classList.contains('open'))startKrishnaOpening()}).observe(gate,{attributes:true,attributeFilter:['class']});
// Keep continuous petals behind the opening, then reveal them with the invitation.
const openingPetalVisibility=new MutationObserver(()=>{const active=!!document.querySelector('.krishna-opening:not(.finished)');document.querySelectorAll('.flower-shower').forEach(el=>el.style.visibility=active?'hidden':'')});openingPetalVisibility.observe(document.body,{childList:true,subtree:false});
// Lamp coordinates follow the painted terraces (portrait image coordinates).
const lampRows=[[[50,87.5]],[[17,88.6],[83,88.6]],[[5,74.4],[22,76],[39,76.9],[61,76.9],[79,76],[95,74.4]],[[12,69.3],[26,70.5],[42,70.9],[58,70.9],[74,70.5],[88,69.3]],[[18,65.4],[30,66.2],[43,66.6],[57,66.6],[70,66.2],[82,65.4]],[[22,61.5],[32,62.4],[44,62.8],[56,62.8],[68,62.4],[78,61.5]],[[16,57.4],[20,58.5],[28,59.4],[39,59.7],[50,59.8],[61,59.7],[72,59.4],[80,58.5],[84,57.4]],[[21,54.9],[28,54.7],[34,54.8],[73,54.8],[79,54.9]]];
function configureNightScene(scene){if(scene.dataset.enhanced)return;scene.dataset.enhanced='true';scene.querySelector('.opening-skip')?.remove();const garden=scene.querySelector('.opening-garden');const sizeScene=()=>{const r=scene.getBoundingClientRect();const scale=innerWidth>=700?r.height/1672:Math.max(r.width/941,r.height/1672);return {w:r.width,h:r.height,iw:941*scale,ih:1672*scale}};const patches=[];lampRows.forEach((row,ri)=>row.forEach(([x,y],li)=>{const patch=document.createElement('div');patch.className='lamp-light-patch';const radius=ri<2?4.8:2.5;const place=()=>{const d=sizeScene();const px=(d.w-d.iw)/2+x/100*d.iw;const py=(d.h-d.ih)/2+y/100*d.ih;const rx=radius/100*d.iw;const ry=radius/100*d.ih;patch.style.maskImage=`radial-gradient(ellipse ${rx}px ${ry}px at ${px}px ${py}px,black 35%,transparent 100%)`;patch.style.webkitMaskImage=patch.style.maskImage};place();addEventListener('resize',place);garden.append(patch);patches.push({patch,ri,li})}));const sky=scene.querySelector('.opening-sky');for(let i=0;i<38;i++){const star=document.createElement('span');star.className='moving-star';star.style.cssText=`left:${8+Math.random()*84}%;top:${Math.random()*90}%;--star-duration:${12+Math.random()*18}s;--star-delay:${-Math.random()*15}s`;sky.append(star)}const bursts=[{x:28,y:12,s:170},{x:72,y:10,s:180},{x:50,y:19,s:150},{x:18,y:23,s:135},{x:82,y:23,s:140}];scene.querySelectorAll('.opening-firework').forEach((burst,i)=>{const b=bursts[i];burst.style.setProperty('--sky-x',b.x+'%');burst.style.setProperty('--sky-y',b.y+'%');burst.style.setProperty('--sky-size',`min(${b.s}px, 36vw)`);const reflection=document.createElement('div');reflection.className='water-firework';reflection.style.cssText=`--reflection-x:${i%2?85:15}%;--reflection-width:24%;--reflection-delay:${6+i*.6}s`;reflection.innerHTML='<img src="golden-firework.svg" alt="">';scene.append(reflection);burst.style.setProperty('--burst-delay',(6+i*.6)+'s')});const button=scene.querySelector('.light-diyas');button.onclick=()=>{if(scene.dataset.lighting)return;scene.dataset.lighting='true';scene.classList.add('illuminated');scene.querySelector('.scene-status').textContent='दिये एक-एक करके प्रज्वलित हो रहे हैं।';patches.forEach(({patch,ri,li})=>sceneTimers.push(setTimeout(()=>patch.classList.add('on'),motion?0:ri*650+li*85)));scene.classList.add('celebrating');sceneTimers.push(setTimeout(()=>{scene.classList.add('revealing');scene.querySelector('.scene-status').textContent='Dhiraj and Neha. Your invitation is ready.';scene.querySelector('.opening-continue').focus()},motion?200:10200))};const originalEscape=scene.querySelector('.opening-continue');scene.addEventListener('keydown',e=>{if(e.key==='Escape')e.stopImmediatePropagation()},true)}
new MutationObserver(()=>{const scene=document.querySelector('.krishna-opening');if(scene)configureNightScene(scene)}).observe(document.body,{childList:true});document.querySelector('.skip-envelope')?.remove();
new MutationObserver(()=>{const scene=document.querySelector('.krishna-opening');if(!scene||scene.dataset.welcomeReady)return;scene.dataset.welcomeReady='true';scene.querySelector('.opening-caption')?.remove();const names=scene.querySelector('.opening-names');names.innerHTML='<p class="welcome-line">Welcome to the wedding of</p><h2>Dhiraj & Neha</h2><svg class="wedding-flourish" viewBox="0 0 180 40" fill="none" aria-hidden="true"><path d="M6 20H57M123 20H174M61 20C72 20 70 6 79 10C84 12 81 18 77 19M119 20C108 20 110 6 101 10C96 12 99 18 103 19M65 25C76 25 77 32 85 27M115 25C104 25 103 32 95 27" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/><path d="M90 9C94 15 99 18 90 28C81 18 86 15 90 9Z" stroke="currentColor"/><circle cx="90" cy="20" r="2.5" fill="currentColor"/><circle cx="5" cy="20" r="2" fill="currentColor"/><circle cx="175" cy="20" r="2" fill="currentColor"/></svg><p class="wedding-location">Uttar Pradesh</p><button class="opening-continue">Read the invitation ↓</button>';names.querySelector('button').onclick=()=>{sceneTimers.forEach(clearTimeout);scene.classList.add('finished');document.body.style.overflow='';document.querySelector('.hero h1').focus({preventScroll:true});setTimeout(()=>scene.remove(),1200)};const watch=new MutationObserver(()=>{if(scene.classList.contains('revealing')&&!scene.dataset.revealDelayed){scene.dataset.revealDelayed='true';scene.classList.remove('revealing');sceneTimers.push(setTimeout(()=>scene.classList.add('revealing'),motion?0:900));watch.disconnect()}});watch.observe(scene,{attributes:true,attributeFilter:['class']})}).observe(document.body,{childList:true});
// Generated gold lotus, bansuri and peacock-feather ornament.
new MutationObserver(()=>{const flourish=document.querySelector('.opening-names svg.wedding-flourish');if(flourish){const img=document.createElement('img');img.className='wedding-flourish generated-ornament';img.src='krishna-wedding-ornament.svg';img.alt='Gold lotus, Krishna flute and peacock feather ornament';flourish.replaceWith(img)}}).observe(document.body,{childList:true,subtree:true});
// Float matching jasmine petals while the envelope is visible.
if(!motion){const petals=document.createElement('div');petals.className='envelope-petals';petals.setAttribute('aria-hidden','true');for(let i=0;i<23;i++){const petal=document.createElement('span');const n=Math.floor(Math.random()*9);petal.className='jasmine-fall';petal.style.cssText=`left:${Math.random()*100}%;--size:${16+Math.random()*14}px;--px:${n%3*50}%;--py:${Math.floor(n/3)*50}%;--duration:${11+Math.random()*9}s;--delay:${-Math.random()*20}s;--drift:${-65+Math.random()*130}px`;petals.append(petal)}document.body.append(petals);const gateWatch=new MutationObserver(()=>{if(gate.classList.contains('open')){petals.classList.add('leaving');setTimeout(()=>petals.remove(),1400);gateWatch.disconnect()}});gateWatch.observe(gate,{attributes:true,attributeFilter:['class']})}
new MutationObserver(()=>{const scene=document.querySelector('.krishna-opening');if(scene&&!scene.dataset.smoothEntrance){scene.dataset.smoothEntrance='true';scene.classList.add('scene-entering');requestAnimationFrame(()=>requestAnimationFrame(()=>scene.classList.remove('scene-entering')))}}).observe(document.body,{childList:true});
// Start audio directly from the envelope tap so mobile browsers permit playback.
const envelopeMusicTrigger=document.getElementById('envelope-seal');if(envelopeMusicTrigger)envelopeMusicTrigger.addEventListener('click',()=>{if(weddingAudio.paused){musicStatus.textContent='';weddingAudio.play().then(syncMusic).catch(()=>{syncMusic();musicStatus.textContent='Tap the music button to start the music.'})}},{once:true});
// Fewer petals, with near, middle and distant sizes rather than a uniform shower.
const envelopePetalLayer=document.querySelector('.envelope-petals');if(envelopePetalLayer){envelopePetalLayer.replaceChildren();const count=innerWidth<650?11:16;for(let i=0;i<count;i++){const p=document.createElement('span');p.className='jasmine-fall';const variant=Math.floor(Math.random()*9);const depth=i%4;const size=depth===0?24+Math.random()*8:depth===1?15+Math.random()*6:8+Math.random()*6;p.style.cssText=`left:${(i+.3+Math.random()*.4)/count*100}%;--size:${size}px;--px:${variant%3*50}%;--py:${Math.floor(variant/3)*50}%;--duration:${depth===0?13+Math.random()*4:19+Math.random()*9}s;--delay:${-Math.random()*28}s;--drift:${-40+Math.random()*80}px;--start-angle:${Math.random()*360}deg;--petal-opacity:${depth>1?.35+Math.random()*.2:.65+Math.random()*.2};--petal-blur:${depth===3?.45:0}px`;envelopePetalLayer.append(p)}}
